UPDATE ssinfo_tools t JOIN ssinfo_seo_pages p ON p.slug=CONCAT('/tools/',t.slug) SET t.data=JSON_SET(t.data,'$.seoTitle',JSON_EXTRACT(p.data,'$.seoTitle')) WHERE p.status='active' AND JSON_EXTRACT(p.data,'$.seoTitle') IS NOT NULL AND JSON_UNQUOTE(JSON_EXTRACT(p.data,'$.seoTitle'))<>'';
